const body = $input.first().json.body || $input.first().json;
const agentCode = (body.agentCode || 'COWORKER').toUpperCase();
let assignedWorkflow = '';
let targetWebhook = '';

if (agentCode === 'ASSISTANT') {
  assignedWorkflow = 'Sleeply - Secretary Gmail & Calendar Manager';
  targetWebhook = 'https://n8n-dev1.auto-node.tech/webhook/sleeply-secretary-agent';
} else if (agentCode === 'MANAGER') {
  assignedWorkflow = 'Sleeply - Manager Nightly Monitor & Report';
  targetWebhook = 'https://n8n-dev1.auto-node.tech/webhook/sleeply-manager-agent';
} else {
  assignedWorkflow = 'Sleeply - Co-worker GitHub & Code Executor';
  targetWebhook = 'https://n8n-dev1.auto-node.tech/webhook/sleeply-coworker-agent';
}

return [{
  json: {
    ...body,
    orchestrated: true,
    agentCode,
    taskTitle: body.taskTitle || 'Tarea Orquestada Sleeply',
    taskDescription: body.taskDescription || 'Procesamiento de rol automatizado con Meta AI',
    operatingMode: body.operatingMode || 'awake',
    assignedWorkflow,
    targetWebhook,
    timestamp: new Date().toISOString()
  }
}];
